import{_ as a,o as s,c as o,a5 as i}from"./chunks/framework.BwlBv862.js";const h=JSON.parse('{"title":"Diagnósticos e evidências seguras","description":"","frontmatter":{"title":"Diagnósticos e evidências seguras","docId":"developer.diagnostics","translationKey":"developer.diagnostics","locale":"pt","audience":"developer","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"bd492eda2007394d29d152e20ec0dba70614f06e6d29b75a3b741ed6b23f11b4","translationRevision":"ab5428fcdf0023310edc0028b5d52b2d42c19c0ab7270e53c32a39a2a7f5ee50","order":130},"headers":[],"relativePath":"pt/developer/diagnostics.md","filePath":"pt/developer/diagnostics.md","lastUpdated":1794611623000}'),t={name:"pt/developer/diagnostics.md"};function r(n,e,d,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[i(`<h1 id="diagnostics-and-safe-evidence" tabindex="-1">Diagnósticos e evidências seguras <a class="header-anchor" href="#diagnostics-and-safe-evidence" aria-label="Permalink to &quot;Diagnósticos e evidências seguras {#diagnostics-and-safe-evidence}&quot;">​</a></h1><h2 id="goal-and-prerequisites" tabindex="-1">Objetivo e pré-requisitos <a class="header-anchor" href="#goal-and-prerequisites" aria-label="Permalink to &quot;Objetivo e pré-requisitos {#goal-and-prerequisites}&quot;">​</a></h2><p>Colete evidências suficientes para localizar uma falha sem reter segredos de conta nem confundir diagnóstico com recuperação. Use um host privado de teste e saiba qual <a href="./transports.html">transporte</a> está selecionado. O aplicativo instala um coletor de sessão; componentes de status navegam até ele em vez de adicionar entradas durante a renderização.</p><h2 id="inspect-a-failure" tabindex="-1">Inspecione uma falha <a class="header-anchor" href="#inspect-a-failure" aria-label="Permalink to &quot;Inspecione uma falha {#inspect-a-failure}&quot;">​</a></h2><ol><li>Abra a ação de status contextual da conexão, plugin, rodada de sincronização ou atualizador com falha. O foco de teclado expõe a ação de registro do desktop assim como passar o ponteiro.</li><li>Filtre por origem, gravidade e texto e inspecione o contexto e a contagem de repetições da entrada selecionada.</li><li>Copie entradas selecionadas ou filtradas quando explicarem o problema. Revise exportações antes de compartilhá-las.</li><li>Compare a integridade nativa com a observação do frontend:</li></ol><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> info</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> health</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">target/debug/tiktools</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --json</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> system</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> doctor</span></span></code></pre></div><p>Uma sondagem de LIVE desconectada pode ser ignorada. Uma capacidade compilada não comprova disponibilidade na execução. O painel da interface é não modal no desktop; layouts estreitos usam <code>/debug</code> com um local de retorno. A exportação nativa de texto usa <code>system.saveFile</code>; navegadores baixam localmente.</p><h2 id="understand-retention" tabindex="-1">Entenda a retenção <a class="header-anchor" href="#understand-retention" aria-label="Permalink to &quot;Entenda a retenção {#understand-retention}&quot;">​</a></h2><p><code>src/web/shared/diagnostics/log.ts</code> limita o histórico a 2.000 entradas e 2 MiB de UTF-8 serializado. Eventos consecutivos correspondentes de origem/entidade em até cinco segundos são combinados com uma contagem de repetições. A remoção de dados sensíveis ocorre antes da retenção, incluindo credenciais reconhecidas e locais secretos de URLs; segredos arbitrários de terceiros sem rótulo nem sempre podem ser reconhecidos. Não adicione configurações brutas, cookies, parâmetros RPC ou corpos HTTP aos coletores.</p><h2 id="expected-result-and-status" tabindex="-1">Resultado esperado e status <a class="header-anchor" href="#expected-result-and-status" aria-label="Permalink to &quot;Resultado esperado e status {#expected-result-and-status}&quot;">​</a></h2><p>O visualizador oferece histórico de sessão limitado e navegação de contexto, não um registro durável de auditoria. Recarregar/desmontar limpa a memória. Limpar o histórico não limpa um erro de conexão nem corrige sua causa. IDs de requisição do Cloud podem ajudar a correlacionar um envelope seguro de falha; a cobertura de origens segue os coletores instalados e não garante a captura de todo erro de registro ou nativo.</p><h2 id="verify-and-recover" tabindex="-1">Verifique e recupere <a class="header-anchor" href="#verify-and-recover" aria-label="Permalink to &quot;Verifique e recupere {#verify-and-recover}&quot;">​</a></h2><p>Execute <code>bun scripts/task.ts test web diagnostics</code> e inspecione o <a href="https://github.com/nglmercer/TikTools-app/tree/remake/src/web/shared/diagnostics" target="_blank" rel="noreferrer">código do coletor</a>. Reproduza remoção de dados sensíveis, descarte e comportamento de eventos repetidos com valores sintéticos. Para conflito, comando desconhecido ou credencial expirada, volte ao fluxo de recuperação responsável. Copiar uma entrada de diagnóstico coleta evidência; nunca repete uma ação nem aprova uma nova política de confiança.</p>`,13)])])}const m=a(t,[["render",r]]);export{h as __pageData,m as default};
